from z3 import *

v = 10
b = 60
r = 18
k = 3
lam = 4

# Create the matrix variables
X = [[Int(f"x_{i}_{j}") for j in range(b)] for i in range(v)]

solver = Solver()

# Constraints: 0 or 1
for i in range(v):
    for j in range(b):
        solver.add(Or(X[i][j] == 0, X[i][j] == 1))

# Row sums: 18
for i in range(v):
    solver.add(Sum([X[i][j] for j in range(b)]) == r)

# Column sums: 3
for j in range(b):
    solver.add(Sum([X[i][j] for i in range(v)]) == k)

# Inner product: 4
for i1 in range(v):
    for i2 in range(i1 + 1, v):
        solver.add(Sum([X[i1][j] * X[i2][j] for j in range(b)]) == lam)

# Check satisfiability
if solver.check() == sat:
    model = solver.model()
    result = []
    for i in range(v):
        for j in range(b):
            result.append(model.evaluate(X[i][j]).as_long())
    print(result)
else:
    print("UNSATISFIABLE")
